/// <summary>扫除 Mop Up: Color fills the zone along u, then is wiped away in the same direction.</summary>
public sealed class MopUpEffect : EffectGenerator, ILoopable
{
    public const string EffectId = "MopUp";

    public MopUpEffect()
        : base(EffectId, new EffectParamSchema("Mop Up", "扫除", 1, 7, true, true, EffectMath.Trio, false))
